-- 1. Agentic AI — NPR 12,000
insert into public.courses (category_id, slug, title, subtitle, description, fee, duration, level, modes, badge, is_ai_integrated, is_featured, is_published, sort_order, icon, accent, tools, outcomes, prerequisites, includes, careers, curriculum, faqs, installments)
select (select id from public.categories where slug = 'ai-data'), r.slug, r.title, r.subtitle, r.description, r.fee, r.duration, r.level, r.modes, r.badge, r.is_ai_integrated, r.is_featured, r.is_published, r.sort_order, r.icon, r.accent, r.tools, r.outcomes, r.prerequisites, r.includes, r.careers, r.curriculum, r.faqs, r.installments
from jsonb_populate_record(null::public.courses, convert_from(decode('', 'base64'), 'UTF8')::jsonb) r
on conflict (slug) do nothing;

